with unpacked as (select id, plan, currency, tier_prices, discounts, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, slice(tier_limits, 1, 2) as first_two_limits, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price from price_tiers where plan in ('basic', 'pro', 'starter')) select case when avg_tier_price >= 27 then 'PREMIUM' else 'STANDARD' end as avg_tier_price_tier, plan, round(sum(avg_tier_price) / nullif(count(case when currency = 'EUR' then 1 end), 0), 2) as avg_tier_price_per_eur, count(distinct plan) as distinct_plans from unpacked group by cube (case when avg_tier_price >= 27 then 'PREMIUM' else 'STANDARD' end, plan) having distinct_plans > 1 order by avg_tier_price_per_eur desc;
